// Turn one sitemap.xml document into the list of URLs this run will audit.
//
// No XML node is used on purpose: a sitemap is machine-generated and flat, so a regex over
// <loc>...</loc> is enough, and it keeps this template free of extra node dependencies.

// ---- Tuning knobs ----------------------------------------------------------------
const MAX_URLS = 50;           // hard cap on Analyze calls per run. This is the cost control.
const SAMPLE_MODE = 'rotate';  // 'rotate' | 'spread' | 'first'  (see the README)
const EXCLUDE_PATTERNS = [     // URLs never worth auditing (add your own)
  /\/wp-json\//i,
  /\/feed\/?$/i,
];
// ----------------------------------------------------------------------------------

// Only used to make the digest readable; a failure here must not break the sweep.
let sitemapUrl = '';
try {
  sitemapUrl = $('Fetch Sitemap').params.url || '';
} catch (e) {
  sitemapUrl = '';
}

const raw = $input.first().json.data;
const xml = typeof raw === 'string' ? raw : JSON.stringify(raw == null ? '' : raw);

// A failed sitemap fetch must never look like a clean sweep, so this throws instead of
// returning zero items. The node's error output routes it to the Slack failure alert.
if (!xml || xml.length < 20) {
  throw new Error(
    `Sitemap at ${sitemapUrl || 'the configured URL'} came back empty. Nothing was audited — ` +
      'check the URL returns XML, not an HTML error page.'
  );
}

const isSitemapIndex = /<sitemapindex[\s>]/i.test(xml);

const decodeEntities = (s) =>
  s
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'");

const locs = [];
const locRe = /<loc>\s*([^<]+?)\s*<\/loc>/gi;
let m;
while ((m = locRe.exec(xml)) !== null) locs.push(m[1]);

const childSitemaps = [];
const seen = new Set();
const pages = [];

for (const rawLoc of locs) {
  const url = decodeEntities(String(rawLoc).trim());
  if (!/^https?:\/\//i.test(url)) continue; // drop relative or non-http entries
  if (/\.xml(\.gz)?($|\?)/i.test(url)) {
    childSitemaps.push(url); // a nested sitemap, not a page — only the first level is read
    continue;
  }
  if (EXCLUDE_PATTERNS.some((p) => p.test(url))) continue;
  const key = url.split('#')[0]; // fragments are the same document
  if (seen.has(key)) continue;
  seen.add(key);
  pages.push(key);
}

if (!pages.length) {
  if (isSitemapIndex || childSitemaps.length) {
    throw new Error(
      `This is a sitemap index: it lists ${childSitemaps.length} child sitemap(s) and no pages. ` +
        'Only the first level is read, so nothing was audited. Point Fetch Sitemap at a child ' +
        `sitemap (e.g. ${childSitemaps[0] || 'n/a'}) or duplicate the fetch once per child.`
    );
  }
  throw new Error(
    `No <loc> entries found at ${sitemapUrl || 'the configured URL'}. Nothing was audited — ` +
      'that document is probably not a sitemap (an HTML 404 page is the usual culprit).'
  );
}

const total = pages.length;
// Rotates once per calendar day (UTC) so consecutive runs audit different slices.
const dayIndex = Math.floor(Date.now() / 86400000);

let selected;
let coverageNote;

if (total <= MAX_URLS) {
  selected = pages;
  coverageNote = 'whole sitemap (under the MAX_URLS cap)';
} else if (SAMPLE_MODE === 'first') {
  selected = pages.slice(0, MAX_URLS);
  coverageNote = `first ${MAX_URLS} URLs only — the rest of the site is never audited`;
} else if (SAMPLE_MODE === 'spread') {
  const stride = Math.max(1, Math.floor(total / MAX_URLS));
  const offset = dayIndex % stride;
  selected = [];
  for (let i = offset; i < total && selected.length < MAX_URLS; i += stride) selected.push(pages[i]);
  coverageNote = `spread sample: every ${stride}th URL from offset ${offset} — the whole site is sampled each run, full coverage in ~${stride} runs`;
} else {
  const windows = Math.ceil(total / MAX_URLS);
  const window = dayIndex % windows;
  const start = window * MAX_URLS;
  selected = [...new Set(pages.slice(start, start + MAX_URLS))];
  coverageNote = `rotating window ${window + 1} of ${windows}: sitemap entries ${start + 1}-${start + selected.length} — full coverage every ${windows} runs`;
}

return selected.map((url) => ({
  json: {
    url,
    sitemapUrl,
    totalFound: total,
    auditedCount: selected.length,
    childSitemapCount: childSitemaps.length,
    isSitemapIndex,
    sampleMode: total <= MAX_URLS ? 'all' : SAMPLE_MODE,
    coverageNote,
  },
}));

// Classify ONE audited URL. The headline case is `soft-error`: HTTP 200 plus error-page
// content — the soft 404 that every status-code monitor and every uptime checker calls healthy.
//
// This is a HEURISTIC. It reads the page's own title and H1 text and matches them against a
// pattern list. It will be wrong sometimes in both directions — see the README's Troubleshooting
// section before wiring it to anything that pages a human.

// ---- The whole heuristic lives in these two constants. Extend them, don't scatter regexes. ----
const ERROR_PAGE_PATTERNS = [
  /\b404\b/,
  /\b410\b/,
  /\b50[0234]\b/,
  /page not found/i,
  /not found/i,
  /no such page/i,
  /does ?n[o']?t exist/i,
  /we can ?n[o']?t find/i,
  /page introuvable/i, // fr
  /page non trouv/i, // fr
  /erreur serveur/i, // fr
  /seite nicht gefunden/i, // de
  /nicht gefunden/i, // de
  /p[aá]gina no encontrada/i, // es
  /pagina non trovata/i, // it
  /internal server error/i,
  /server error/i,
  /something went wrong/i,
  /page unavailable/i,
  /service unavailable/i,
  /temporarily unavailable/i,
  /under maintenance/i,
  /access denied/i,
  /forbidden/i,
  /oops/i,
];

// Real pages whose own title legitimately matches the patterns above — a blog post called
// "404 errors explained", a docs page called "HTTP status codes". Add them here rather than
// weakening ERROR_PAGE_PATTERNS for the whole site.
const KNOWN_GOOD_URLS = [
  // /\/blog\/404-errors-explained$/,
];
// ------------------------------------------------------------------------------------------

const d = $input.item.json;
const src = $('Loop Over Sitemap URLs').item.json;

const q = d.quality || {};
const meta = d.metadata || {};
const headings = d.headings || {};

const httpStatus =
  typeof q.httpStatus === 'number'
    ? q.httpStatus
    : typeof meta.httpStatus === 'number'
      ? meta.httpStatus
      : null;

const title = String(meta.title || '').trim();
const h1s = Array.isArray(headings.h1)
  ? headings.h1.map((h) => String(h).trim()).filter(Boolean)
  : [];

const firstMatch = (text) => {
  for (const p of ERROR_PAGE_PATTERNS) if (p.test(text)) return String(p);
  return null;
};

const titleMatch = title ? firstMatch(title) : null;
let h1Text = '';
let h1Match = null;
for (const h of h1s) {
  const hit = firstMatch(h);
  if (hit) {
    h1Text = h;
    h1Match = hit;
    break;
  }
}

const statusLabel = httpStatus === null ? 'unknown status' : `HTTP ${httpStatus}`;

// Precedence: report the cause once, worst / most explanatory signal first. The soft case is
// checked LAST so a page that is honestly returning 404 is never mislabelled as a soft 404.
let status = 'ok';
let signal = `${statusLabel} · title "${title || '(empty)'}"`;

if (KNOWN_GOOD_URLS.some((p) => p.test(src.url))) {
  status = 'ok';
  signal = 'excluded by KNOWN_GOOD_URLS';
} else if (httpStatus !== null && httpStatus >= 400) {
  status = 'hard-error';
  signal = `${statusLabel} — the server reports the error honestly`;
} else if (q.hasCaptcha === true) {
  status = 'captcha';
  signal = `CAPTCHA / bot wall served instead of the page (${statusLabel})`;
} else if (q.isBlank === true) {
  status = 'blank';
  signal = `rendered blank, no visible content (${statusLabel})`;
} else if (titleMatch) {
  status = 'soft-error';
  signal = `${statusLabel} but <title> "${title}" matches ${titleMatch}`;
} else if (h1Match) {
  status = 'soft-error';
  signal = `${statusLabel} but <h1> "${h1Text}" matches ${h1Match}`;
}

return [
  {
    json: {
      url: src.url,
      status,
      signal,
      httpStatus: httpStatus === null ? 0 : httpStatus,
      title,
      h1: h1s[0] || '',
      isBlank: q.isBlank === true,
      hasCaptcha: q.hasCaptcha === true,
      screenshotLink: (d.screenshot && d.screenshot.link) || '',
      checkedAt: new Date().toISOString(),
      sitemapUrl: src.sitemapUrl || '',
      totalFound: src.totalFound || 0,
      auditedCount: src.auditedCount || 0,
      coverageNote: src.coverageNote || '',
    },
  },
];

// One digest per sweep, listing ONLY the problem URLs — plus an honest coverage line, because
// "0 problems" out of 50 audited URLs on a 5,000-page site is not the same as "the site is fine".
const SEVERITY = { 'soft-error': 0, 'hard-error': 1, blank: 2, captcha: 3, unreachable: 4, ok: 9 };
const ICON = {
  'soft-error': '🕳️',
  'hard-error': '🚫',
  blank: '⬜',
  captcha: '🤖',
  unreachable: '💥',
};
const MAX_LINES = 40; // Slack caps a message near 40k characters

const rows = $input.all().map((i) => i.json);
const problems = rows
  .filter((r) => r.status && r.status !== 'ok')
  .sort((a, b) => (SEVERITY[a.status] ?? 9) - (SEVERITY[b.status] ?? 9));

const softCount = problems.filter((r) => r.status === 'soft-error').length;
const first = rows[0] || {};
const totalFound = first.totalFound || rows.length;
const auditedCount = first.auditedCount || rows.length;
const coverageNote = first.coverageNote || '';
const sitemapUrl = first.sitemapUrl || '';

const coverageLine = `📊 Audited *${auditedCount}* of *${totalFound}* URL(s) found in ${
  sitemapUrl ? `<${sitemapUrl}|the sitemap>` : 'the sitemap'
}${coverageNote ? ` — ${coverageNote}` : ''}.`;

const lines = [];
lines.push(
  `*🕳️ Error-page sweep* — ${problems.length} problem URL(s), of which *${softCount}* serve an error page with a non-error HTTP status`
);
lines.push(coverageLine);
lines.push('');

for (const r of problems.slice(0, MAX_LINES)) {
  const icon = ICON[r.status] || '⚠️';
  const shot = r.screenshotLink ? ` · <${r.screenshotLink}|view capture>` : '';
  lines.push(`${icon} <${r.url}|${r.url}> — *${r.status}*: ${r.signal}${shot}`);
}
if (problems.length > MAX_LINES) {
  lines.push(`_…and ${problems.length - MAX_LINES} more — see the Google Sheet._`);
}

lines.push('');
lines.push(
  '_`soft-error` = HTTP 200 with error-page content. Detection is a heuristic on title/H1 text._'
);

return [
  {
    json: {
      report: lines.join('\n'),
      allClear: `✅ *Error-page sweep clean* — no error pages found.\n${coverageLine}`,
      problemCount: problems.length,
      softErrorCount: softCount,
      okCount: rows.length - problems.length,
      auditedCount,
      totalFound,
      coverageNote,
    },
  },
];
